<?php require_once __DIR__ . '/ResourceController.php'; final class ThreatController { public static function index(string $method, ?string $id = null, ?string $action = null): never { if ($method === 'GET' && $id === null) ResourceController::list('threats', ['Super Admin', 'Admin']); if ($method === 'GET' && $id !== null) ResourceController::show('threats', $id, ['Super Admin', 'Admin']); if ($method === 'PUT' && $id !== null && $action === 'status') { RoleMiddleware::allow(['Super Admin', 'Admin']); $data = Validation::body(); Validation::required($data, ['status']); if (!in_array($data['status'], ['Detected', 'Investigating', 'Quarantined', 'Resolved', 'Ignored'], true)) Response::error('Invalid threat status', 'INVALID_STATUS', 422); Response::success('Threat status updated', MySQLRepository::updateThreatStatus(Validation::id($id), $data['status'])); } Response::error('Method not allowed', 'METHOD_NOT_ALLOWED', 405); } }
